async function runEngagementRoll(html, roleTitle = "Engagement Roll Summary") {
  // --- Attacker Roll ---
  let skill_att = html.find('[name="skill_attacker"]').val();
  let skillLevel_att = parseInt(html.find('[name="skillLevel_attacker"]').val()) || 0;
  let link_att = parseInt(html.find('[name="link_attacker"]').val()) || 0;
  let complexity_att = parseInt(html.find('[name="complexity_attacker"]').val()) || 8;
  let modifiers_att = parseInt(html.find('[name="modifiers_attacker"]').val()) || 0;
  let tmm_att = parseInt(html.find('[name="tmm_attacker"]').val()) || 0;
  let naturalAptitude_att = html.find('[name="naturalAptitude_attacker"]').is(':checked');

  let rollFormula_att = naturalAptitude_att ? "3d6kh2x12 + @skillLevel + @link + @modifiers" : "2d6x12 + @skillLevel + @link + @modifiers";
  let roll_att = new Roll(rollFormula_att, {skillLevel: skillLevel_att, link: link_att, modifiers: modifiers_att});
  await roll_att.evaluate();

  let result_att = roll_att.total;
  let baseMargin_att = result_att - complexity_att;
  let margin_att = baseMargin_att + tmm_att; // Apply TMM

  // --- Defender Roll ---
  let skill_def = html.find('[name="skill_defender"]').val();
  let skillLevel_def = parseInt(html.find('[name="skillLevel_defender"]').val()) || 0;
  let link_def = parseInt(html.find('[name="link_defender"]').val()) || 0;
  let complexity_def = parseInt(html.find('[name="complexity_defender"]').val()) || 8;
  let modifiers_def = parseInt(html.find('[name="modifiers_defender"]').val()) || 0;
  let tmm_def = parseInt(html.find('[name="tmm_defender"]').val()) || 0;
  let naturalAptitude_def = html.find('[name="naturalAptitude_defender"]').is(':checked');

  let rollFormula_def = naturalAptitude_def ? "3d6kh2x12 + @skillLevel + @link + @modifiers" : "2d6x12 + @skillLevel + @link + @modifiers";
  let roll_def = new Roll(rollFormula_def, {skillLevel: skillLevel_def, link: link_def, modifiers: modifiers_def});
  await roll_def.evaluate();

  let result_def = roll_def.total;
  let baseMargin_def = result_def - complexity_def;
  let margin_def = baseMargin_def + tmm_def; // Apply TMM

  // --- Determine Outcome & Range ---
  let winner = "";
  let rangeResult = "";
  let tacticalNote = "";
  let netMoS = 0;

  let bothFailed = (baseMargin_att < 0 && baseMargin_def < 0);

  if (bothFailed) {
    rangeResult = "Range is Long (Both parties failed)";
    winner = "None";
  } else if (margin_att === margin_def) {
    rangeResult = "Range is Medium (Tie)";
    winner = "Tie";
  } else if (margin_att > margin_def) {
    winner = "Attacker Wins";
    rangeResult = "Winner Picks Range";
  } else {
    winner = "Defender Wins";
    rangeResult = "Winner Picks Range";
  }

  // --- Net MoS & Maneuvering Tailing Logic ---
  if (winner === "Attacker Wins") {
    if (baseMargin_def >= 0) {
      netMoS = baseMargin_att - baseMargin_def;
    } else {
      netMoS = baseMargin_att + Math.abs(baseMargin_def);
    }

    if (netMoS >= 5) {
      tacticalNote = "Winner is Tailing the Target!";
    } else if (baseMargin_att >= 5) {
      tacticalNote = "Winner successfully maneuvers!";
    }
  } else if (winner === "Defender Wins") {
    if (baseMargin_att >= 0) {
      netMoS = baseMargin_def - baseMargin_att;
    } else {
      netMoS = baseMargin_def + Math.abs(baseMargin_att);
    }

    if (netMoS >= 5) {
      tacticalNote = "Winner is Tailing the Target!";
    } else if (baseMargin_def >= 5) {
      tacticalNote = "Winner successfully maneuvers!";
    }
  }

  // Send Roll visual details to chat (Consistent formatting)
  await roll_att.toMessage({ speaker: ChatMessage.getSpeaker(), content: `<strong>Attacker Roll (${skill_att})</strong><br>Roll: ${result_att} | Margin: ${margin_att}` });
  await roll_def.toMessage({ speaker: ChatMessage.getSpeaker(), content: `<strong>Defender Roll (${skill_def})</strong><br>Roll: ${result_def} | Margin: ${margin_def}` });

  // Summary Chat Message
  let content = `
    <strong>${roleTitle}</strong><br>
    <strong>Outcome:</strong> ${winner}<br>
    <strong>Range Determination:</strong> ${rangeResult}<br>
    ${tacticalNote ? `<strong>Tactical Status:</strong> ${tacticalNote}<br>` : ""}
    <hr>
    <p><strong>Continue Engagement?</strong></p>
    <button class="tactical-choice" data-action="yes">Yes (Reroll)</button>
    <button class="tactical-choice" data-action="no">No (End Combat)</button>
    <button class="tactical-choice" data-action="disengage">Disengage</button>
  `;

  ChatMessage.create({
    speaker: ChatMessage.getSpeaker(),
    content: content
  });
}

