              let e_tmm = parseInt(disDialogHtml.find('[name="tmm_evader"]').val()) || 0;
              let e_nat = disDialogHtml.find('[name="naturalAptitude_evader"]').is(':checked');

              let rollFormula_e = e_nat ? "3d6kh2x12 + @skillLevel + @link + @modifiers" : "2d6x12 + @skillLevel + @link + @modifiers";
              let roll_e = new Roll(rollFormula_e, {skillLevel: e_skill, link: e_link, modifiers: e_mods});
              await roll_e.evaluate();

              let baseMargin_e = roll_e.total - e_complexity;
              let margin_e = baseMargin_e + e_tmm;

              let winnerText = "";

              if (baseMargin_p < 0 && baseMargin_e < 0) {
                winnerText = "Both parties failed! Combat Automatically Breaks Off.";
              } else if (margin_p === margin_e) {
                let tieRoll = await new Roll("1d6").evaluate();
                let tieVal = tieRoll.total;
                if (tieVal <= 3) {
                  winnerText = `Tie-breaker (Rolled ${tieVal}): <strong>Evader Wins</strong> (Winner Decides if Combat Continues)`;
                } else {
                  winnerText = `Tie-breaker (Rolled ${tieVal}): <strong>Pursuer Wins</strong> (Winner Decides if Combat Continues)`;
                }
              } else if (margin_p > margin_e) {
                winnerText = "<strong>Pursuer Wins!</strong> (Winner Decides if Combat Continues)";
              } else {
                winnerText = "<strong>Evader Wins!</strong> (Winner Decides if Combat Continues)";
              }

              await roll_p.toMessage({ speaker: ChatMessage.getSpeaker(), content: `<strong>Disengagement - Pursuer Roll (${p_skillName})</strong><br>Roll: ${roll_p.total} | Margin: ${margin_p}` });
              await roll_e.toMessage({ speaker: ChatMessage.getSpeaker(), content: `<strong>Disengagement - Evader Roll (${e_skillName})</strong><br>Roll: ${roll_e.total} | Margin: ${margin_e}` });

              ChatMessage.create({
                speaker: ChatMessage.getSpeaker(),
                content: `<strong>Disengagement Result</strong><br>${winnerText}`
              });
            }
          }
        }
      }).render(true);
    }
  });
}

